CREATE TABLE IF NOT EXISTS `decks` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `cards` (`id` TEXT NOT NULL, `deckId` TEXT NOT NULL, `front` TEXT NOT NULL, `back` TEXT NOT NULL, `example` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`deckId`) REFERENCES `decks`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_cards_deckId` ON `cards` (`deckId`);
CREATE TABLE IF NOT EXISTS `schedules` (`cardId` TEXT NOT NULL, `phase` TEXT NOT NULL, `step` INTEGER, `stability` REAL, `difficulty` REAL, `dueAt` INTEGER NOT NULL, `lastReviewAt` INTEGER, `firstReviewedAt` INTEGER, `revision` INTEGER NOT NULL, PRIMARY KEY(`cardId`), FOREIGN KEY(`cardId`) REFERENCES `cards`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_schedules_dueAt` ON `schedules` (`dueAt`);
CREATE INDEX IF NOT EXISTS `index_schedules_firstReviewedAt` ON `schedules` (`firstReviewedAt`);
CREATE TABLE IF NOT EXISTS `review_logs` (`id` TEXT NOT NULL, `cardId` TEXT NOT NULL, `deckId` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `rating` INTEGER NOT NULL, `reviewedAt` INTEGER NOT NULL, `durationMs` INTEGER NOT NULL, `beforeSchedule` TEXT NOT NULL, `afterSchedule` TEXT NOT NULL, `undoneAt` INTEGER, PRIMARY KEY(`id`), FOREIGN KEY(`cardId`) REFERENCES `cards`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`deckId`) REFERENCES `decks`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_review_logs_cardId` ON `review_logs` (`cardId`);
CREATE INDEX IF NOT EXISTS `index_review_logs_deckId` ON `review_logs` (`deckId`);
CREATE INDEX IF NOT EXISTS `index_review_logs_sessionId` ON `review_logs` (`sessionId`);
CREATE INDEX IF NOT EXISTS `index_review_logs_reviewedAt` ON `review_logs` (`reviewedAt`);
CREATE TABLE IF NOT EXISTS `settings` (`id` INTEGER NOT NULL, `newCardsPerDay` INTEGER NOT NULL, `themeMode` TEXT NOT NULL, `schemaVersion` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `anki_models` (`id` TEXT NOT NULL, `sourceModelId` TEXT NOT NULL, `contentHash` TEXT NOT NULL, `name` TEXT NOT NULL, `kind` INTEGER NOT NULL, `originalStockKind` INTEGER NOT NULL, `fieldNames` TEXT NOT NULL, `templates` TEXT NOT NULL, `css` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_anki_models_contentHash` ON `anki_models` (`contentHash`);
CREATE TABLE IF NOT EXISTS `anki_notes` (`id` TEXT NOT NULL, `sourceGuid` TEXT NOT NULL, `modelId` TEXT NOT NULL, `fields` TEXT NOT NULL, `tags` TEXT NOT NULL, `mediaNamespace` TEXT NOT NULL, `revision` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`modelId`) REFERENCES `anki_models`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE UNIQUE INDEX IF NOT EXISTS `index_anki_notes_sourceGuid` ON `anki_notes` (`sourceGuid`);
CREATE INDEX IF NOT EXISTS `index_anki_notes_modelId` ON `anki_notes` (`modelId`);
CREATE INDEX IF NOT EXISTS `index_anki_notes_mediaNamespace` ON `anki_notes` (`mediaNamespace`);
CREATE TABLE IF NOT EXISTS `anki_cards` (`cardId` TEXT NOT NULL, `noteId` TEXT NOT NULL, `ordinal` INTEGER NOT NULL, PRIMARY KEY(`cardId`), FOREIGN KEY(`cardId`) REFERENCES `cards`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`noteId`) REFERENCES `anki_notes`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE UNIQUE INDEX IF NOT EXISTS `index_anki_cards_noteId_ordinal` ON `anki_cards` (`noteId`, `ordinal`);
CREATE TABLE IF NOT EXISTS `anki_deck_sources` (`sourceDeckId` TEXT NOT NULL, `originalFullName` TEXT NOT NULL, `localDeckId` TEXT NOT NULL, PRIMARY KEY(`sourceDeckId`, `originalFullName`), FOREIGN KEY(`localDeckId`) REFERENCES `decks`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_anki_deck_sources_localDeckId` ON `anki_deck_sources` (`localDeckId`);
CREATE TABLE IF NOT EXISTS `anki_media` (`namespace` TEXT NOT NULL, `originalName` TEXT NOT NULL, `sha256` TEXT NOT NULL, `size` INTEGER NOT NULL, `mime` TEXT NOT NULL, PRIMARY KEY(`namespace`, `originalName`));
CREATE INDEX IF NOT EXISTS `index_anki_media_sha256` ON `anki_media` (`sha256`);
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
